package com.acme.notes;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class NoteApiTest {

    @Autowired
    private MockMvc mvc;   // test wiring only; production code uses constructor injection

    @Test
    void createThenListUsesEnvelopeAndPagination() throws Exception {
        mvc.perform(post("/api/notes").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"first\",\"body\":\"hello\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.success").value(true))
                .andExpect(jsonPath("$.data.title").value("first"));

        mvc.perform(get("/api/notes?page=0&size=500"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.pagination.page").value(1))
                .andExpect(jsonPath("$.pagination.size").value(100))
                .andExpect(jsonPath("$.data[0].title").value("first"));
    }

    @Test
    void missingNoteIsAnEnvelopeError() throws Exception {
        mvc.perform(get("/api/notes/999"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.success").value(false))
                .andExpect(jsonPath("$.errors[0].code").value("NOTE_NOT_FOUND"));
    }

    @Test
    void updateFixesTitleAndBody() throws Exception {
        String response = mvc.perform(post("/api/notes").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"typo\",\"body\":\"hello\"}"))
                .andReturn().getResponse().getContentAsString();
        long id = com.jayway.jsonpath.JsonPath.read(response, "$.data.id");

        mvc.perform(put("/api/notes/" + id).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"fixed\",\"body\":\"hello world\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.success").value(true))
                .andExpect(jsonPath("$.data.title").value("fixed"))
                .andExpect(jsonPath("$.data.body").value("hello world"));

        mvc.perform(get("/api/notes/" + id))
                .andExpect(jsonPath("$.data.title").value("fixed"));
    }

    @Test
    void updatingMissingNoteIsAnEnvelopeError() throws Exception {
        mvc.perform(put("/api/notes/999").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"fixed\",\"body\":\"hello\"}"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.success").value(false))
                .andExpect(jsonPath("$.errors[0].code").value("NOTE_NOT_FOUND"));
    }
}
